sparql_tries.sparql:
SELECT ?compName (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?c rc:affectsComponent ?comp .
  ?comp rc:name ?compName .
  ?comp skos:broader ?parent .
  FILTER EXISTS { ?c1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" . }
  FILTER EXISTS { ?c2 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" . }
}
GROUP BY ?compName
ORDER BY DESC(?n)
LIMIT 10

SELECT ?campno (COUNT(DISTINCT ?makeName) AS ?brandCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?brands) WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campno ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI","KIA","GENESIS"))
}
GROUP BY ?campno
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?brandCount) ?campno

SELECT ?topName (COUNT(DISTINCT ?model) AS ?n) WHERE {
  ?c a rc:RecallCampaign ; rc:affectsComponent ?comp ; rc:affects ?v .
  ?v rc:ofModel ?model .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?p }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?n)
LIMIT 5

SELECT ?topName (COUNT(DISTINCT ?c) AS ?n) WHERE {
  ?make rc:name "GENESIS" .
  ?model rc:ofMake ?make .
  ?v rc:ofModel ?model .
  ?c rc:affects ?v ;
     rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?p }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?n)

SELECT DISTINCT ?campaignNumber ?defect WHERE {
  ?r a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:defectSummary ?defect .
  FILTER(CONTAINS(LCASE(?defect), "connecting rod") && CONTAINS(LCASE(?defect), "bearing") && CONTAINS(LCASE(?defect), "wear"))
} ORDER BY ?campaignNumber
